package gadomancymodern.client;
import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;
/** Original geometry and UV coordinates. */
public class ManipulationModels {
public static ModelPart random(){var mesh=new MeshDefinition();var root=mesh.getRoot();root.addOrReplaceChild("shape2",CubeListBuilder.create().texOffs(0,5).addBox(-1.0f, -2.0f, 0.41f, 2, 2, 1),PartPose.offsetAndRotation(0.0f, 22.0f, 4.0f,0.0f, 0.0f, 0.0f));root.addOrReplaceChild("shape3",CubeListBuilder.create().texOffs(0,8).addBox(-1.0f, -3.4f, 1.0f, 2, 2, 1),PartPose.offsetAndRotation(0.0f, 22.0f, 4.0f,0.3490659f, 0.0f, 0.0f));root.addOrReplaceChild("shape4",CubeListBuilder.create().texOffs(0,0).addBox(-1.0f, -1.0f, 0.0f, 2, 4, 1),PartPose.offsetAndRotation(0.0f, 22.0f, 4.0f,-0.7853982f, 0.0f, 0.0f));root.addOrReplaceChild("shape5",CubeListBuilder.create().texOffs(0,11).addBox(-1.0f, -4.25f, 2.24f, 2, 2, 1),PartPose.offsetAndRotation(0.0f, 22.0f, 4.0f,0.7853982f, 0.0f, 0.0f));return LayerDefinition.create(mesh,8,16).bakeRoot();}
public static ModelPart portal(){var mesh=new MeshDefinition();var root=mesh.getRoot();root.addOrReplaceChild("shape1",CubeListBuilder.create().texOffs(0,3).addBox(-1.0f, -2.0f, 0.41f, 2, 5, 1),PartPose.offsetAndRotation(0.0f, 20.0f, 3.533333f,0.0f, 0.0f, 0.0f));root.addOrReplaceChild("shape2",CubeListBuilder.create().texOffs(0,0).addBox(-1.0f, -1.0f, 0.0f, 2, 2, 1),PartPose.offsetAndRotation(0.0f, 23.0f, 3.5f,-0.7853982f, 0.0f, 0.0f));root.addOrReplaceChild("shape3",CubeListBuilder.create().texOffs(0,12).addBox(0.0f, 0.0f, 0.0f, 2, 2, 1),PartPose.offsetAndRotation(-1.0f, 21.0f, 2.5f,0.7853982f, 0.0f, 0.0f));root.addOrReplaceChild("shape4",CubeListBuilder.create().texOffs(0,9).addBox(0.0f, 0.0f, 0.0f, 2, 2, 1),PartPose.offsetAndRotation(-1.0f, 19.0f, 2.5f,0.7853982f, 0.0f, 0.0f));root.addOrReplaceChild("shape5",CubeListBuilder.create().texOffs(6,0).addBox(0.0f, -1.0f, 0.03f, 2, 4, 1),PartPose.offsetAndRotation(-1.0f, 18.0f, 3.5f,0.7853982f, 0.0f, 0.0f));return LayerDefinition.create(mesh,32,32).bakeRoot();}
}
